items=[];entries=[]
def add(n,src,kind,scans,lines,words,statement,reason,reconstruction='',verdict='kept',check='agrees'):
    iid=f'SA04-{n}'
    items.append(dict(id=iid,sources=[f'{P}#{j}' for j in src],kind=kind,cote='93',scans=scans,lines=[f'pro/{P}_transcription.tex:{lines}'],his_words=words,statement=statement,reconstruction=reconstruction or 'Modern vocabulary only; no missing manuscript hypothesis silently supplied.',check=check,check_reason=reason))
    for j in src:
        entries.append(dict(entry_id=f'{P}#{j}',item_id=iid,verdict=verdict if j==src[0] else 'merged',reason=(reason if j==src[0] else f'Merged with entry #{src[0]}: '+reason)))

