add(36,[36],'unproved claim',[50],'89','f est un polynôme','For an entire Banach-valued f and nonzero finite trigonometric polynomial p(theta), a uniform bound |p(theta)| norm f(re^{i theta}) <= M r^alpha implies degree at most floor(alpha).','Fourier extraction isolates the least-frequency nonzero coefficient of p, while higher frequencies decay after rescaling. This verifies the degree conclusion, although the printed limiting integral omits 2pi.')
