add(78,[78],'unproved claim',[56,66],'211–215;578','Si X compact','For compact X, singular cohomology with compact supports, defined as the direct limit of H*(X,X minus K), equals ordinary singular cohomology; finiteness and Euler numbers agree.','K=X is terminal among compact subsets, proving the asserted identification directly.')
