add(86,[86],'reading question',[58],'310–313','chi(R^n)=...=(-1)^n','The last Euclidean-space calculation writes ordinary chi where compact-support chi is needed.','Odd n gives 1=-1 if read literally, contrary to the preceding displayed table. This flags the source, without inserting exclamation marks into it.')
